1	//! The declared command's output, into the transcript the server already
2	//! serves.
3	//!
4	//! A declared body executes IN the server process, so there is no worker drain
5	//! between the command and the sequencer: the activity's transcript seam is
6	//! drained here and published straight through
7	//! [`ActivityEventPublisher`](crate::activity_publisher::ActivityEventPublisher),
8	//! which is the same durable append, retention bound, and live fan-out an agent
9	//! step's transcript goes through after crossing the wire. Downstream — the
10	//! cursor reads, the WS tail, the ops console — cannot tell the two apart, and
11	//! is not meant to.
12	//!
13	//! # Losing a transcript never fails a command
14	//!
15	//! Publishing is observability, and the command's replay-authoritative result is
16	//! its own. A store that refuses an event costs a log line and the event, never
17	//! the activity: the first failure of a run names the reason, the rest are
18	//! counted, and the total is reported when the command ends. That is the same
19	//! coalescing discipline the worker-side drain uses, for the same reason — a
20	//! failing sink must not turn one line of output into one log line per line of
21	//! output.
22	
23	use aion_core::ActivityEvent;
24	use tokio::sync::mpsc;
25	
26	use crate::activity_publisher::ActivityEventPublisher;
27	
28	/// Drain `events` into `publisher` until the activity's transcript seam closes.
29	///
30	/// Returns when the sender is dropped — which the declared-command executor does
31	/// as soon as its command has finished — so the caller can await this and know
32	/// every observed line has been offered to the sequencer.
33	pub(crate) async fn publish_declared_transcript(
34	    publisher: ActivityEventPublisher,
35	    mut events: mpsc::UnboundedReceiver<ActivityEvent>,
36	) {
37	    let mut dropped: u64 = 0;
38	    while let Some(event) = events.recv().await {
39	        if let Err(error) = publisher.publish(&event).await {
40	            if dropped == 0 {
41	                tracing::warn!(
42	                    %error,
43	                    operation = "declared_command_dispatch",
44	                    workflow_id = %event.workflow_id,
45	                    activity_id = %event.activity_id,
46	                    attempt = event.attempt,
47	                    "declared command transcript: the sequencer refused an output line; the \
48	                     command is unaffected and further refusals are counted, not logged"
49	                );
50	            }
51	            dropped = dropped.saturating_add(1);
52	        }
53	    }
54	    if dropped > 0 {
55	        tracing::warn!(
56	            dropped,
57	            operation = "declared_command_dispatch",
58	            "declared command transcript: output lines were not retained"
59	        );
60	    }
61	}
