115	/// MANDATORY NEGATIVE CONTROL (a): concurrent writers on ONE
116	/// `(wf,act,attempt)` stream. Many `publish` calls race the same head; the
117	/// read-head -> append -> on-conflict-retry loop must serialize them so the
118	/// final durable sequence is strictly monotonic 0..N-1 with NO gap and NO
119	/// duplicate — proving the retry loop (not the store) enforces monotonicity.
120	#[tokio::test(flavor = "multi_thread")]
121	async fn concurrent_writers_produce_gapless_monotonic_store_seq()
122	-> Result<(), Box<dyn std::error::Error>> {
123	    let publisher = publisher(256)?;
124	    let writers = 32u64;
125	    let mut handles = Vec::new();
126	    for worker_seq in 0..writers {
127	        let publisher = publisher.clone();
128	        handles.push(tokio::spawn(async move {
129	            publisher
130	                .publish(&event(0, worker_seq, false, "concurrent"))
131	                .await
132	        }));
133	    }
134	    let mut assigned = Vec::new();
135	    for handle in handles {
136	        if let Some(store_seq) = handle.await?? {
137	            assigned.push(store_seq);
138	        }
139	    }
140	    assigned.sort_unstable();
141	    // Every writer won exactly one distinct, contiguous store_seq.
142	    assert_eq!(
143	        assigned,
144	        (0..writers).collect::<Vec<_>>(),
145	        "concurrent writers must produce a gapless, duplicate-free monotonic sequence"
146	    );
147	    // The durable tail agrees: exactly `writers` records, seqs 0..N-1 in order.
148	    let tail = publisher.replay_from(&key(0), 0).await?;
149	    assert_eq!(
150	        tail.iter().map(|r| r.store_seq).collect::<Vec<_>>(),
151	        (0..writers).collect::<Vec<_>>()
152	    );
153	    Ok(())
154	}
