156	/// MANDATORY NEGATIVE CONTROL (b): failover dedup. A dying worker and an
157	/// adopting worker BOTH emit for one `(wf,act,attempt)` (the same session
158	/// resumes across failover). Modeled as two publishers sharing ONE store
159	/// (the server owns durability, §5.3) racing appends: the commit-allocated
160	/// `store_seq` collapses both emitters into one monotonic stream with no
161	/// gap/dup — the transcript is not duplicated or reordered by the double-emit.
162	#[tokio::test(flavor = "multi_thread")]
163	async fn failover_double_emit_dedupes_to_one_monotonic_stream()
164	-> Result<(), Box<dyn std::error::Error>> {
165	    // ONE durable store (the server), TWO publisher clones = the dying +
166	    // adopting worker's events both flowing through the single server writer.
167	    let store = Arc::new(InMemoryObservabilityStore::default());
168	    let dying = ActivityEventPublisher::new(store.clone(), capacity(256)?);
169	    let adopting = ActivityEventPublisher::new(store, capacity(256)?);
170	
171	    let mut handles = Vec::new();
172	    for worker_seq in 0..16u64 {
173	        let dying = dying.clone();
174	        let adopting = adopting.clone();
175	        handles.push(tokio::spawn(async move {
176	            // Both survivors emit the SAME logical event for this attempt.
177	            let a = dying.publish(&event(0, worker_seq, false, "dying")).await;
178	            let b = adopting
179	                .publish(&event(0, worker_seq, false, "adopting"))
180	                .await;
181	            (a, b)
182	        }));
183	    }
184	    let mut assigned = Vec::new();
185	    for handle in handles {
186	        let (a, b) = handle.await?;
187	        if let Some(seq) = a? {
188	            assigned.push(seq);
189	        }
190	        if let Some(seq) = b? {
191	            assigned.push(seq);
192	        }
193	    }
194	    assigned.sort_unstable();
195	    // 16 events x 2 emitters = 32 durable records, each with a DISTINCT,
196	    // contiguous store_seq — the double-emit does not corrupt monotonicity.
197	    assert_eq!(
198	        assigned,
199	        (0..32).collect::<Vec<_>>(),
200	        "failover double-emit must land a gapless monotonic store_seq stream"
201	    );
202	    let tail = dying.replay_from(&key(0), 0).await?;
203	    let seqs: Vec<u64> = tail.iter().map(|r| r.store_seq).collect();
204	    assert_eq!(seqs, (0..32).collect::<Vec<_>>());
205	    Ok(())
206	}
