208	/// MANDATORY NEGATIVE CONTROL: the WRONG-allocator case. A process-local
209	/// `AtomicU64` (the `ClusterEventPublisher` pattern the design forbids for
210	/// `store_seq`) is shown to produce COLLIDING sequences when two "survivors"
211	/// each start their own counter after a failover — proving the counter
212	/// belongs in the commit, not the process. The commit-allocated publisher
213	/// (above) does NOT exhibit this; this test pins the failure mode we avoid.
214	#[tokio::test]
215	async fn process_local_atomic_counter_collides_across_survivors()
216	-> Result<(), Box<dyn std::error::Error>> {
217	    use std::sync::atomic::{AtomicU64, Ordering};
218	    // Two survivors, each with its OWN fresh process-local counter (exactly
219	    // what a per-process AtomicU64 does after restart/failover).
220	    let dying = AtomicU64::new(0);
221	    let adopting = AtomicU64::new(0);
222	    let dying_seq = dying.fetch_add(1, Ordering::SeqCst);
223	    let adopting_seq = adopting.fetch_add(1, Ordering::SeqCst);
224	    // Both minted the SAME sequence — a collision. This is the bug the
225	    // commit-allocated design exists to prevent.
226	    assert_eq!(
227	        dying_seq, adopting_seq,
228	        "process-local counters collide across survivors (the forbidden pattern)"
229	    );
230	
231	    // By contrast the commit-allocated publisher over a shared store never
232	    // collides: the two survivors get DISTINCT sequences.
233	    let store = Arc::new(InMemoryObservabilityStore::default());
234	    let a = ActivityEventPublisher::new(store.clone(), capacity(8)?);
235	    let b = ActivityEventPublisher::new(store, capacity(8)?);
236	    let sa = a.publish(&event(0, 1, false, "a")).await?;
237	    let sb = b.publish(&event(0, 2, false, "b")).await?;
238	    assert_ne!(
239	        sa, sb,
240	        "commit-allocated store_seq must be distinct across survivors"
241	    );
242	    assert_eq!((sa, sb), (Some(0), Some(1)));
243	    Ok(())
244	}
