246	/// The live-stream + resume-by-`store_seq` gate: a subscriber tails live
247	/// events, and a reconnecting client resumes from the durable tail by
248	/// `store_seq` then splices onto the live broadcast with NO gap and NO
249	/// duplicate at the seam.
250	#[tokio::test]

246	/// The live-stream + resume-by-`store_seq` gate: a subscriber tails live
247	/// events, and a reconnecting client resumes from the durable tail by
248	/// `store_seq` then splices onto the live broadcast with NO gap and NO
249	/// duplicate at the seam.
250	#[tokio::test]
251	async fn live_stream_then_resume_by_store_seq_has_no_gap() -> Result<(), Box<dyn std::error::Error>>
252	{
253	    let publisher = publisher(64)?;
254	    // Persist a few events (as if the client was connected then dropped).
255	    for seq in 0..3u64 {
256	        publisher.publish(&event(0, seq, false, "early")).await?;
257	    }
258	    // Client reconnects having last seen store_seq 1. Splice: attach the live
259	    // stream BEFORE reading the durable tail (gap-free splice), with the
260	    // resume cursor as after_seq so live re-delivery of <=cursor is suppressed.
261	    let mut live = publisher.subscribe(key(0), Some(1));
262	    let replay = publisher.replay_from(&key(0), 2).await?;
263	    // The durable tail from the cursor is exactly seq 2 (the one it missed).
264	    assert_eq!(
265	        replay.iter().map(|r| r.store_seq).collect::<Vec<_>>(),
266	        vec![2]
267	    );
268	    // Now new live events arrive.
269	    publisher.publish(&event(0, 10, false, "live-3")).await?;
270	    publisher.publish(&event(0, 11, false, "live-4")).await?;
271	    // The live splice yields seq 3 then 4 — no gap, no re-delivery of <=1.
272	    let first = live.next().await.ok_or("missing live-3")??;
273	    assert_eq!(first.store_seq, Some(3));
274	    let second = live.next().await.ok_or("missing live-4")??;
275	    assert_eq!(second.store_seq, Some(4));
276	    Ok(())
277	}
