462	    let ordinal_zero = ActivityId::from_sequence_position(0);
463	    let first = ActivityEvent {
464	        activity_id: ordinal_zero.clone(),
465	        attempt: 1,
466	        ..event(1, 1, false, "generation one")
467	    };
468	    let second = ActivityEvent {
469	        run_id: generation_two(),
470	        ..first.clone()
471	    };
472	
473	    assert_eq!(publisher.publish(&first).await?, Some(0));
474	    assert_eq!(
475	        publisher.publish(&second).await?,
476	        Some(0),
477	        "generation two's first event is its own stream head, not generation one's second record"
478	    );
