480	    let first_key = ActivityStreamKey::of(&first);
481	    let second_key = ActivityStreamKey::of(&second);
482	    assert_ne!(first_key, second_key);
483	    // The keys agree on every axis except the run — the collision under test.
484	    assert_eq!(first_key.workflow_id, second_key.workflow_id);
485	    assert_eq!(first_key.activity_id, second_key.activity_id);
486	    assert_eq!(first_key.attempt, second_key.attempt);
